<script setup lang="ts">
import {computed,defineAsyncComponent,nextTick,ref,watch} from 'vue'
import type {ColumnConfig,FilterConfig,RowData,UserColumnConfig} from '../../types'
import type {MappingConfig,MappingItem,NumberRule} from '../columns/types'
import {evaluateCell} from '../columns/evaluate'
import {defaultColumnFilter,operatorLabels,operatorsByType,type ColumnFilterConfig,type FilterType} from '../filters/model'
import {cloneData,getValue,typedKey,withValue} from '../../runtime/value'
import {getColumnSectionAccess,resolveSettingsPolicy,type SettingsPolicy,type ColumnSettingsSection} from './policy'
import {readRichDocument,richText,type RichDocument} from '../rich-text/document'
import BusinessCell from '../../components/BusinessCell.vue'
import ColorSelect from '../../components/ColorSelect.vue'
import TableIcon from '../../components/TableIcon.vue'
import DialogFrame from '../../ui/DialogFrame.vue'
const RichEditor=defineAsyncComponent(()=>import('../rich-text/RichEditor.vue'))
const props=defineProps<{column:ColumnConfig;columns:readonly ColumnConfig[];row?:RowData;settingsPolicy?:SettingsPolicy;actionsVisible?:boolean}>()
const emit=defineEmits<{patch:[patch:UserColumnConfig];validation:[errors:string[]];trial:[row:RowData];actions:[]}>()
const root=ref<HTMLElement>(),closed=ref<Set<string>>(new Set()),templateOpen=ref(false),templateDraft=ref<RichDocument>({ops:[{insert:'\n'}]}),templateError=ref(''),trialText=ref(''),trialType=ref<'text'|'number'|'boolean'|'null'>('text'),trialResult=ref<ReturnType<typeof evaluateCell>>()
const errors=ref<Record<string,string>>({}),buffers=ref<Record<string,string>>({})
const settingsPolicy=computed(()=>props.settingsPolicy??resolveSettingsPolicy())
const access=(section:ColumnSettingsSection)=>getColumnSectionAccess(props.column,section,settingsPolicy.value)
const can=(key:'content'|'format'|'filter'|'mapping'|'template'|'trial')=>{const value=access(key==='format'?'number':key);return value.visible&&!value.disabled}
const content=computed(()=>props.column.content??{})
const numeric=computed(()=>['number','currency','percent'].includes(props.column.type??''))
const filter=computed(()=>defaultColumnFilter(props.column))
const mapping=computed<MappingConfig>(()=>({enabled:false,type:numeric.value?'number':'text',presentation:'tag',empty:'—',unknown:'未匹配',items:[],...props.column.mapping}))
const number=computed<NumberRule>(()=>({enabled:false,style:props.column.type==='currency'?'currency':props.column.type==='percent'?'percent':'decimal',currency:'CNY',minimumFractionDigits:2,maximumFractionDigits:2,useGrouping:true,scale:1,percentBase:'ratio',sign:'auto',...props.column.numberRule}))
const copyableColumns=computed(()=>props.columns.filter(column=>column.kind!=='actions'&&column.id!==props.column.id))
function report(key:string,message=''){if(message)errors.value[key]=message;else delete errors.value[key];emit('validation',Object.values(errors.value))}
function patchContent(changes:NonNullable<UserColumnConfig['content']>){if(can('content'))emit('patch',{content:{...content.value,...changes}})}
function patchFilter(changes:Partial<ColumnFilterConfig>){if(can('filter'))emit('patch',{filter:{...filter.value,...changes}})}
function typeFilter(type:FilterType){patchFilter({type,operators:[...operatorsByType[type]]})}
function operatorToggle(operator:FilterConfig['operator'],checked:boolean){patchFilter({operators:checked?[...new Set([...filter.value.operators,operator])]:filter.value.operators.filter(item=>item!==operator)})}
function patchMapping(changes:Partial<MappingConfig>){if(can('mapping'))emit('patch',{mapping:{...mapping.value,...changes}})}
function mapItem(index:number,changes:Partial<MappingItem>){patchMapping({items:mapping.value.items.map((item,position)=>position===index?{...item,...changes}:item)})}
const primitiveType=(value:unknown)=>value===null?'null':typeof value==='number'?'number':typeof value==='boolean'?'boolean':'text'
function mapType(index:number,type:string){if(!can('mapping'))return;mapItem(index,{value:type==='null'?null:type==='number'?0:type==='boolean'?true:''});delete buffers.value['map'+index];report('map'+index)}
function mapValue(index:number,text:string){
  if(!can('mapping'))return
  const item=mapping.value.items[index];if(!item)return
  const type=primitiveType(item.value),key='map'+index;buffers.value[key]=text
  if(type==='number'&&(!text.trim()||!Number.isFinite(Number(text)))){report(key,'映射原值需要有效数字');return}
  report(key);mapItem(index,{value:type==='number'?Number(text):type==='boolean'?text==='true':type==='null'?null:text})
}
function mapColor(index:number,key:'color'|'background'|'border',value:string){
  if(!can('mapping'))return
  const token=`mapcolor${index}${key}`;buffers.value[token]=value
  if(value!==''&&!/^#[\da-f]{6}$/i.test(value)){report(token,'映射颜色应为六位十六进制颜色');return}
  report(token);const item={...mapping.value.items[index]!};if(value==='')delete item[key];else item[key]=value
  patchMapping({items:mapping.value.items.map((old,i)=>i===index?item:old)})
}
function addMap(){if(mapping.value.items.length>=200)return;patchMapping({items:[...mapping.value.items,{id:crypto.randomUUID(),value:mapping.value.type==='number'?mapping.value.items.length:mapping.value.type==='boolean'?true:'',label:''}]})}
function moveMap(index:number,offset:number){if(!can('mapping'))return;const items=[...mapping.value.items],target=index+offset;if(target<0||target>=items.length)return;const [item]=items.splice(index,1);items.splice(target,0,item!);buffers.value={};errors.value={};emit('validation',[]);patchMapping({items})}
function removeMap(index:number){if(!can('mapping'))return;buffers.value={};errors.value={};emit('validation',[]);patchMapping({items:mapping.value.items.filter((_,i)=>i!==index)})}
function presetMap(){patchMapping({enabled:true,type:'boolean',presentation:'tag',items:[{id:crypto.randomUUID(),value:true,label:'是',color:'#167457',background:'#eaf7f2'},{id:crypto.randomUUID(),value:false,label:'否',color:'#526177',background:'#f0f2f6'}]})}
function patchNumber(changes:Partial<NumberRule>){if(can('format'))emit('patch',{numberRule:{...number.value,...changes}})}
function fraction(key:'minimumFractionDigits'|'maximumFractionDigits',value:string){if(!can('format'))return;const amount=Number(value);if(!Number.isInteger(amount)||amount<0||amount>8){report('number'+key,'小数位数应在 0–8 之间');return}report('number'+key);const changes:Partial<NumberRule>={[key]:amount};if(key==='minimumFractionDigits'&&amount>(number.value.maximumFractionDigits??2))changes.maximumFractionDigits=amount;if(key==='maximumFractionDigits'&&amount<(number.value.minimumFractionDigits??0))changes.minimumFractionDigits=amount;patchNumber(changes)}
function precision(mode:'fixed'|'maximum'){patchNumber({minimumFractionDigits:mode==='fixed'?(number.value.maximumFractionDigits??2):0})}
function numericPreset(kind:'integer'|'currency'|'percent'|'ten-thousand'){patchNumber({enabled:true,style:kind==='integer'||kind==='ten-thousand'?'decimal':kind,currency:'CNY',minimumFractionDigits:kind==='integer'?0:2,maximumFractionDigits:kind==='integer'?0:2,percentBase:'ratio',scale:kind==='ten-thousand'?10000:1,prefix:'',suffix:kind==='ten-thousand'?'万元':'',useGrouping:kind!=='percent',sign:'auto'})}
function manualOption(index:number,key:'value'|'label',text:string){
  if(!can('filter'))return
  const item=filter.value.options[index];if(!item)return
  const type=primitiveType(item.value),token='manual'+index;let value:unknown=text
  if(key==='value'){
    buffers.value[token]=text
    if(type==='number'&&(!text.trim()||!Number.isFinite(Number(text)))){report(token,'选项原值需要有效数字');return}
    if(type==='boolean'&&!['true','false'].includes(text)){report(token,'布尔选项原值应为 true 或 false');return}
    value=type==='number'?Number(text):type==='boolean'?text==='true':type==='null'?null:text
    report(token)
  }
  patchFilter({options:filter.value.options.map((option,i)=>i===index?{...option,[key]:value}:option)})
}
function manualType(index:number,type:string){if(!can('filter'))return;delete buffers.value['manual'+index];report('manual'+index);patchFilter({options:filter.value.options.map((item,i)=>i===index?{...item,value:type==='number'?0:type==='boolean'?true:type==='null'?null:''}:item)})}
function clearManualDrafts(){for(const key of Object.keys(buffers.value))if(key.startsWith('manual'))delete buffers.value[key];for(const key of Object.keys(errors.value))if(key.startsWith('manual'))delete errors.value[key];emit('validation',Object.values(errors.value))}
function removeOption(index:number){if(!can('filter'))return;clearManualDrafts();patchFilter({options:filter.value.options.filter((_,i)=>i!==index)})}
function moveOption(index:number,offset:number){if(!can('filter'))return;const options=[...filter.value.options],target=index+offset;if(target<0||target>=options.length)return;const [item]=options.splice(index,1);options.splice(target,0,item!);clearManualDrafts();patchFilter({options})}
function openTemplate(){if(!can('template'))return;templateDraft.value=readRichDocument(props.column.template?.document,{template:true,fields:props.columns.map(column=>column.id)});templateError.value='';templateOpen.value=true}
function applyTemplate(){if(!can('template'))return;if(!richText(templateDraft.value).trim()){templateError.value='请添加模板内容';return}emit('patch',{template:{enabled:true,document:cloneData(templateDraft.value)}});templateOpen.value=false}
function templatePreset(secondary:boolean){if(!can('template'))return;const other=copyableColumns.value.find(column=>column.field===content.value.secondaryField)??copyableColumns.value[0];const document:RichDocument={ops:[{insert:{field:props.column.id}},{insert:'\n'},...(secondary&&other?[{insert:{field:other.id},attributes:{size:'12px',color:'#64748b'}},{insert:'\n'}]:[])]};emit('patch',{template:{enabled:true,document}})}
function calculate(){
  if(!can('trial'))return
  if(trialType.value==='number'&&(!trialText.value.trim()||!Number.isFinite(Number(trialText.value)))){report('trial','试算原始值不是有效数字');return}
  report('trial');const value=trialType.value==='null'?null:trialType.value==='boolean'?trialText.value==='true':trialType.value==='number'?Number(trialText.value):trialText.value
  const row=withValue(props.row??{},props.column.field,value)
  trialResult.value=evaluateCell(row,props.column,props.columns);emit('trial',row)
}
function toggle(section:string){const next=new Set(closed.value);if(next.has(section))next.delete(section);else next.add(section);closed.value=next}
async function reveal(section:ColumnSettingsSection){if(!access(section).visible)return;closed.value.delete(section);closed.value=new Set(closed.value);await nextTick();root.value?.querySelector<HTMLElement>(`[data-column-section="${section}"]`)?.scrollIntoView?.({block:'start',behavior:'smooth'})}
watch(()=>[props.column.id,props.row,access('trial').visible],()=>{if(!access('trial').visible)return;const raw=props.row?getValue(props.row,props.column.field):'';trialText.value=String(raw??'');trialType.value=primitiveType(raw) as typeof trialType.value;trialResult.value=evaluateCell(props.row??{},props.column,props.columns)},{immediate:true})
watch(()=>filter.value.source,source=>{if(source!=='manual')clearManualDrafts()})
watch([trialText,trialType],()=>{if(can('trial'))calculate()})
watch(()=>[props.column.mapping,props.column.numberRule,props.column.template],()=>{if(can('trial'))calculate()})
watch(()=>[props.column.numberRule?.enabled,props.column.mapping?.enabled],(values,previous)=>{if(values[0]&&!previous[0])void reveal('number');else if(values[1]&&!previous[1])void reveal('mapping')})
defineExpose({reveal})
</script>
<template>
  <div ref="root" class="bt-column-rules">
    <fieldset v-if="access('content').visible" data-column-section="content" class="bt-settings-section bt-settings-control-group" :disabled="access('content').disabled"><div class="bt-settings-section__heading"><h4>内容显示</h4></div>
      <div class="bt-settings-grid bt-settings-grid--two"><label class="bt-settings-field">长文本<select aria-label="长文本" :value="content.wrap??'ellipsis'" :disabled="!can('content')" @change="patchContent({wrap:($event.target as HTMLSelectElement).value as 'ellipsis'|'two'|'wrap'})"><option value="ellipsis">单行省略</option><option value="two">最多两行</option><option value="wrap">自动换行</option></select></label><label class="bt-settings-field">空值显示<input aria-label="空值显示" :value="content.emptyText??column.emptyText??'—'" :disabled="!can('content')" maxlength="100" @input="patchContent({emptyText:($event.target as HTMLInputElement).value})" /></label><label class="bt-settings-field">表头说明<input aria-label="表头说明" :value="content.description??''" :disabled="!can('content')" maxlength="1000" @input="patchContent({description:($event.target as HTMLInputElement).value})" /></label><label v-if="column.type==='date'" class="bt-settings-field">日期格式<select aria-label="日期格式" :value="content.dateFormat??'iso'" :disabled="!can('content')" @change="patchContent({dateFormat:($event.target as HTMLSelectElement).value as 'iso'|'slash'|'cn'})"><option value="iso">2026-09-22</option><option value="slash">2026/09/22</option><option value="cn">2026年09月22日</option></select></label></div>
      <template v-if="column.kind!=='actions'"><label class="bt-settings-check"><input type="checkbox" :checked="!!content.copyable" :disabled="!can('content')" @change="patchContent({copyable:($event.target as HTMLInputElement).checked})" />显示复制内容按钮</label><div v-if="content.secondaryField||content.showSecondary" class="bt-secondary-setting"><label class="bt-settings-check"><input type="checkbox" :checked="!!content.showSecondary" :disabled="!can('content')" @change="patchContent({showSecondary:($event.target as HTMLInputElement).checked})" />在主内容下方显示附加字段</label><label v-if="content.showSecondary" class="bt-settings-field">附加字段<select :value="content.secondaryField" aria-label="附加字段" :disabled="!can('content')" @change="patchContent({secondaryField:($event.target as HTMLSelectElement).value})"><option v-for="other in copyableColumns" :key="other.id" :value="other.field">{{other.title}}</option></select></label></div><button v-else-if="copyableColumns.length" class="bt-settings-text" :disabled="!can('content')" @click="patchContent({showSecondary:true,secondaryField:copyableColumns[0]!.field})">添加附加字段</button></template><button v-else-if="actionsVisible" class="bt-settings-text" @click="emit('actions')">设置操作按钮</button>
    </fieldset>
    <template v-if="column.kind!=='actions'">
      <fieldset v-if="access('filter').visible" data-column-section="filter" class="bt-settings-section bt-settings-control-group" :disabled="access('filter').disabled"><header class="bt-rule-heading"><div><h4>列筛选</h4><p>{{filter.enabled?'已启用 · '+filter.operators.length+' 种条件':'未启用'}}</p></div><button class="bt-settings-text" @click="toggle('filter')">{{closed.has('filter')?'展开':'收起'}}</button></header><div v-show="!closed.has('filter')"><label class="bt-settings-check"><input type="checkbox" :checked="filter.enabled" :disabled="!can('filter')" @change="patchFilter({enabled:($event.target as HTMLInputElement).checked})" />允许列筛选</label><template v-if="filter.enabled"><div class="bt-settings-grid bt-settings-grid--two"><label class="bt-settings-field">筛选类型<select aria-label="筛选类型" :value="filter.type" :disabled="!can('filter')" @change="typeFilter(($event.target as HTMLSelectElement).value as FilterType)"><option v-for="type in [{id:'text',label:'文本'},{id:'number',label:'数字'},{id:'date',label:'日期'},{id:'single',label:'单选'},{id:'multi',label:'多选'},{id:'boolean',label:'布尔'}]" :key="type.id" :value="type.id">{{type.label}}</option></select></label><label class="bt-settings-field">选项来源<select aria-label="选项来源" :value="filter.source" :disabled="!can('filter')" @change="patchFilter({source:($event.target as HTMLSelectElement).value as ColumnFilterConfig['source']})"><option value="data">完整数据中的值</option><option value="mapping">值映射字典</option><option value="manual">手动选项</option><option value="remote">远端选项接口</option></select></label></div><div class="bt-settings-inline"><label class="bt-settings-check"><input type="checkbox" :checked="filter.search" :disabled="!can('filter')" @change="patchFilter({search:($event.target as HTMLInputElement).checked})" />选项支持搜索</label><label class="bt-settings-check"><input type="checkbox" :checked="filter.counts" :disabled="!can('filter')" @change="patchFilter({counts:($event.target as HTMLInputElement).checked})" />显示匹配数量</label></div><p class="bt-settings-note">允许使用的条件</p><div class="bt-settings-inline"><label v-for="operator in operatorsByType[filter.type]" :key="operator" class="bt-settings-check"><input type="checkbox" :checked="filter.operators.includes(operator)" :disabled="!can('filter')" @change="operatorToggle(operator,($event.target as HTMLInputElement).checked)" />{{operatorLabels[operator]}}</label></div><template v-if="filter.source==='manual'"><div v-for="(option,index) in filter.options" :key="index" class="bt-manual-option"><select :aria-label="'选项原值类型 '+(index+1)" :value="primitiveType(option.value)" @change="manualType(index,($event.target as HTMLSelectElement).value)"><option value="text">文本</option><option value="number">数字</option><option value="boolean">布尔</option><option value="null">空值</option></select><input :aria-label="'选项原值 '+(index+1)" :value="buffers['manual'+index]??String(option.value??'')" :disabled="option.value===null" :aria-invalid="!!errors['manual'+index]" @input="manualOption(index,'value',($event.target as HTMLInputElement).value)" /><input :aria-label="'选项文案 '+(index+1)" :value="option.label" @input="manualOption(index,'label',($event.target as HTMLInputElement).value)" /><button class="bt-settings-icon" :aria-label="'上移选项 '+(index+1)" :disabled="index===0" @click="moveOption(index,-1)"><TableIcon name="chevron-up" /></button><button class="bt-settings-icon" :aria-label="'下移选项 '+(index+1)" :disabled="index===filter.options.length-1" @click="moveOption(index,1)"><TableIcon name="chevron-down" /></button><button class="bt-settings-icon" :aria-label="'删除选项 '+(index+1)" @click="removeOption(index)"><TableIcon name="close" /></button></div><button class="bt-settings-text" :disabled="filter.options.length>=1000||!can('filter')" @click="patchFilter({options:[...filter.options,{value:'',label:''}]})">添加选项</button></template><p class="bt-settings-note">选项来自完整数据，不只当前页。关闭已有列筛选会在应用时提示清除，不删除顶部查询。</p></template></div></fieldset>
      <fieldset v-if="access('mapping').visible" data-column-section="mapping" class="bt-settings-section bt-settings-control-group" :disabled="access('mapping').disabled"><header class="bt-rule-heading"><div><h4>值映射</h4><p>{{mapping.enabled?'已启用 · '+mapping.items.length+' 条规则':'未启用 · 显示原字段'}}</p></div><button class="bt-settings-text" @click="toggle('mapping')">{{closed.has('mapping')?'展开':'收起'}}</button></header><div v-show="!closed.has('mapping')"><label class="bt-settings-check"><input type="checkbox" :checked="mapping.enabled" :disabled="!can('mapping')" @change="patchMapping({enabled:($event.target as HTMLInputElement).checked})" />启用值映射</label><template v-if="mapping.enabled"><div class="bt-settings-grid bt-settings-grid--three"><label class="bt-settings-field">默认原值类型<select :value="mapping.type" aria-label="映射默认原值类型" @change="patchMapping({type:($event.target as HTMLSelectElement).value as MappingConfig['type']})"><option value="text">文本</option><option value="number">数字</option><option value="boolean">布尔</option></select></label><label class="bt-settings-field">显示形式<select :value="mapping.presentation" aria-label="映射显示形式" @change="patchMapping({presentation:($event.target as HTMLSelectElement).value as MappingConfig['presentation']})"><option value="text">文字</option><option value="tag">标签</option><option value="dot">圆点 + 文字</option></select></label><label class="bt-settings-field">空值文案<input :value="mapping.empty" aria-label="映射空值文案" @input="patchMapping({empty:($event.target as HTMLInputElement).value})" /></label><label class="bt-settings-field">未匹配文案<input :value="mapping.unknown" aria-label="未匹配文案" @input="patchMapping({unknown:($event.target as HTMLInputElement).value})" /></label></div><label class="bt-settings-check"><input type="checkbox" :checked="!!mapping.sort" @change="patchMapping({sort:($event.target as HTMLInputElement).checked})" />按字典顺序排序</label><div class="bt-mapping-items"><article v-for="(item,index) in mapping.items" :key="item.id??index" class="bt-mapping-item"><div class="bt-mapping-row"><label class="bt-settings-field">原值<select :aria-label="'映射原值类型 '+(index+1)" :value="primitiveType(item.value)" @change="mapType(index,($event.target as HTMLSelectElement).value)"><option value="text">文本</option><option value="number">数字</option><option value="boolean">布尔</option><option value="null">空值</option></select><select v-if="typeof item.value==='boolean'" :aria-label="'映射原值 '+(index+1)" :value="String(item.value)" @change="mapValue(index,($event.target as HTMLSelectElement).value)"><option value="true">true</option><option value="false">false</option></select><input v-else :aria-label="'映射原值 '+(index+1)" :disabled="item.value===null" :value="buffers['map'+index]??String(item.value??'null')" :aria-invalid="!!errors['map'+index]" @input="mapValue(index,($event.target as HTMLInputElement).value)" /></label><span class="bt-mapping-arrow">→</span><label class="bt-settings-field">显示文案<input :aria-label="'映射文案 '+(index+1)" :value="item.label" @input="mapItem(index,{label:($event.target as HTMLInputElement).value})" /></label><div class="bt-mapping-sample"><span :style="{color:item.color,background:item.background,borderColor:item.border,borderStyle:item.border?'solid':undefined,borderWidth:item.border?'1px':undefined}"><TableIcon v-if="item.icon" :name="item.icon" :size="13" />{{item.label||'预览'}}</span></div><div class="bt-settings-sort-actions"><button class="bt-settings-icon" :aria-label="'上移映射 '+(index+1)" :disabled="index===0" @click="moveMap(index,-1)"><TableIcon name="chevron-up" :size="12" /></button><button class="bt-settings-icon" :aria-label="'下移映射 '+(index+1)" :disabled="index===mapping.items.length-1" @click="moveMap(index,1)"><TableIcon name="chevron-down" :size="12" /></button><button class="bt-settings-icon" :aria-label="'删除映射 '+(index+1)" @click="removeMap(index)"><TableIcon name="close" :size="12" /></button></div></div><details class="bt-mapping-details"><summary>颜色和图标</summary><div class="bt-settings-grid bt-settings-grid--three"><div v-for="key in ['color','background','border'] as const" :key="key" class="bt-settings-field"><span>{{({color:'文字颜色',background:'背景颜色',border:'边框颜色'})[key]}}</span><ColorSelect :label="'映射'+(index+1)+key" :model-value="buffers['mapcolor'+index+key]??item[key]??''" @update:model-value="mapColor(index,key,$event)" /></div><label class="bt-settings-field">图标<input :value="item.icon??''" :aria-label="'映射图标 '+(index+1)" maxlength="40" @input="mapItem(index,{icon:($event.target as HTMLInputElement).value})" /></label></div></details></article></div><div class="bt-rule-presets"><button class="bt-settings-button" :disabled="mapping.items.length>=200||!can('mapping')" @click="addMap"><TableIcon name="plus" :size="14" />添加映射</button><button class="bt-settings-text" @click="presetMap">是 / 否预设</button></div><p class="bt-settings-note">数字 1、文本“1”和文本“01”是不同原值。映射只改变显示，不改写字段；筛选、复制和导出保留原值语义。</p></template></div></fieldset>
      <fieldset v-if="numeric&&access('number').visible" data-column-section="number" class="bt-settings-section bt-settings-control-group" :disabled="access('number').disabled">
        <header class="bt-rule-heading"><div><h4>数字格式</h4><p>{{number.enabled?'已启用 · 原始数据不变':'未启用 · 使用字段默认格式'}}</p></div><button class="bt-settings-text" :aria-expanded="!closed.has('number')" @click="toggle('number')">{{closed.has('number')?'展开':'收起'}}</button></header>
        <div v-show="!closed.has('number')"><label class="bt-settings-check"><input type="checkbox" :checked="!!number.enabled" :disabled="!can('format')" @change="patchNumber({enabled:($event.target as HTMLInputElement).checked})" />启用数字格式</label>
          <template v-if="number.enabled">
            <div class="bt-settings-inline bt-number-precision"><span>小数显示</span><div class="bt-settings-segmented" role="group" aria-label="小数位模式"><button :aria-pressed="number.minimumFractionDigits===number.maximumFractionDigits" @click="precision('fixed')">固定</button><button :aria-pressed="number.minimumFractionDigits!==number.maximumFractionDigits" @click="precision('maximum')">最多</button></div><small>下方最少 / 最多位数可继续细调。</small></div>
            <div class="bt-settings-grid bt-settings-grid--three">
              <label class="bt-settings-field">显示格式<select aria-label="数字显示格式" :value="number.style" @change="patchNumber({style:($event.target as HTMLSelectElement).value as 'decimal'|'currency'|'percent'})"><option value="decimal">数字</option><option value="currency">货币</option><option value="percent">百分比</option></select></label>
              <label class="bt-settings-field">最少小数位<input type="number" min="0" max="8" aria-label="最少小数位" :value="number.minimumFractionDigits" @input="fraction('minimumFractionDigits',($event.target as HTMLInputElement).value)" /></label>
              <label class="bt-settings-field">最多小数位<input type="number" min="0" max="8" aria-label="最多小数位" :value="number.maximumFractionDigits" @input="fraction('maximumFractionDigits',($event.target as HTMLInputElement).value)" /></label>
              <label v-if="number.style==='currency'" class="bt-settings-field bt-settings-field--wide">币种<select aria-label="币种" :value="number.currency" @change="patchNumber({currency:($event.target as HTMLSelectElement).value})"><option value="CNY">人民币 ¥</option><option value="USD">美元 $</option><option value="EUR">欧元 €</option><option value="JPY">日元 ¥</option></select></label>
              <label v-if="number.style==='percent'" class="bt-settings-field bt-settings-field--wide">原始值口径<select aria-label="百分比原值口径" :value="number.percentBase" @change="patchNumber({percentBase:($event.target as HTMLSelectElement).value as 'ratio'|'percent'})"><option value="ratio">小数比率（0.12 → 12%）</option><option value="percent">百分数（12 → 12%）</option></select></label>
              <label v-else class="bt-settings-field bt-settings-field--wide">显示单位<select aria-label="显示单位" :value="number.scale" @change="patchNumber({scale:Number(($event.target as HTMLSelectElement).value) as 1|1000|10000|100000000})"><option :value="1">原始单位</option><option :value="1000">千</option><option :value="10000">万</option><option :value="100000000">亿</option></select></label>
              <label class="bt-settings-field">正负号<select aria-label="正负号" :value="number.sign" @change="patchNumber({sign:($event.target as HTMLSelectElement).value as 'auto'|'always'|'accounting'})"><option value="auto">默认</option><option value="always">正数显示 +</option><option value="accounting">负数括号</option></select></label>
              <label class="bt-settings-field">前缀<input aria-label="数字前缀" maxlength="40" :value="number.prefix??''" @input="patchNumber({prefix:($event.target as HTMLInputElement).value})" /></label>
              <label class="bt-settings-field">后缀<input aria-label="数字后缀" maxlength="40" :value="number.suffix??''" @input="patchNumber({suffix:($event.target as HTMLInputElement).value})" /></label>
            </div>
            <label class="bt-settings-check"><input type="checkbox" :checked="number.useGrouping" @change="patchNumber({useGrouping:($event.target as HTMLInputElement).checked})" />千位分隔</label>
            <div class="bt-rule-presets"><span>常用格式</span><button class="bt-settings-text" @click="numericPreset('integer')">整数</button><button class="bt-settings-text" @click="numericPreset('currency')">人民币两位小数</button><button class="bt-settings-text" @click="numericPreset('percent')">百分比</button><button class="bt-settings-text" @click="numericPreset('ten-thousand')">万元两位</button></div>
            <p class="bt-settings-note">仅改变显示；排序、筛选和计算保留原始值。Excel 使用数值及对应格式，不以已四舍五入的文字代替原值。</p>
          </template>
        </div>
      </fieldset>
      <fieldset v-if="access('template').visible" data-column-section="template" class="bt-settings-section bt-settings-control-group" :disabled="access('template').disabled"><header class="bt-rule-heading"><div><h4>富文本显示模板</h4><p>{{column.template?.enabled?'已启用 · 使用列显示模板':'未启用 · 使用字段默认排版'}}</p></div><button class="bt-settings-text" @click="toggle('template')">{{closed.has('template')?'展开':'收起'}}</button></header><div v-show="!closed.has('template')"><label class="bt-settings-check"><input type="checkbox" :checked="!!column.template?.enabled" :disabled="!can('template')" @change="emit('patch',{template:{enabled:($event.target as HTMLInputElement).checked,document:column.template?.document??{ops:[{insert:'\n'}]}}})" />使用列显示模板</label><div class="bt-template-sample"><BusinessCell v-if="column.template?.enabled&&row" :row="row" :column="column" :columns="columns" preview /><span v-else>{{column.template?.document?richText(column.template.document,id=>columns.find(column=>column.id===id)?.title??id):''}}</span></div><div class="bt-rule-presets"><button class="bt-settings-button" :disabled="!can('template')" @click="openTemplate"><TableIcon name="edit" :size="14" />编辑模板</button><button v-if="copyableColumns.length" class="bt-settings-text" :disabled="!can('template')" @click="templatePreset(true)">主字段 + 附加字段双行</button><button class="bt-settings-text" :disabled="!can('template')" @click="templatePreset(false)">使用当前字段</button></div><p class="bt-settings-note">只改变单元格显示。原字段继续用于筛选、排序、编辑和结构化导出；原复制、详情入口不移除。</p></div></fieldset>
      <fieldset v-if="access('trial').visible" data-column-section="trial" class="bt-settings-section bt-settings-control-group" :disabled="access('trial').disabled"><header class="bt-rule-heading"><div><h4>规则试算</h4><p>输入原始值，核对显示与导出</p></div><button class="bt-settings-text" @click="toggle('trial')">{{closed.has('trial')?'展开':'收起'}}</button></header><div v-show="!closed.has('trial')"><div class="bt-settings-grid bt-settings-grid--two"><label class="bt-settings-field">原始值<input v-model="trialText" aria-label="试算原始值" :disabled="trialType==='null'" /></label><label class="bt-settings-field">值类型<select v-model="trialType" aria-label="试算值类型"><option value="text">文本</option><option value="number">数字</option><option value="boolean">布尔（true / false）</option><option value="null">空值</option></select></label></div><button class="bt-settings-text" @click="calculate">试算</button><div v-if="trialResult" class="bt-trial-result" role="status"><small>显示结果</small><strong>{{trialResult.text}}</strong><p>筛选匹配原始值：{{String(trialResult.raw??'空值')}}</p><p>Excel 导出值：{{String(trialResult.exportValue??'空值')}} · {{typeof trialResult.exportValue}}</p><p>Excel 格式：{{trialResult.excelFormat}}</p></div></div></fieldset>
    </template>
    <p v-for="(message,key) in errors" :key="key" class="bt-settings-error" role="alert">{{message}}</p>
    <DialogFrame v-if="templateOpen&&can('template')" title="编辑列显示模板" subtitle="字段用标签插入，数据仍按原字段保存。" wide @close="templateOpen=false"><RichEditor v-model="templateDraft" label="列显示模板" template :columns="columns" :max-chars="3000" /><p v-if="templateError" class="bt-ui-error" role="alert">{{templateError}}</p><template #footer><button class="bt-ui-button" @click="templateOpen=false">取消</button><button class="bt-ui-button primary" @click="applyTemplate">使用模板</button></template></DialogFrame>
  </div>
</template>
